pre.code:
import { loadFont, loadFontFamily } from 'metaowl'

// Single font
await loadFont({
  family: 'MyFont',
  src: '/fonts/MyFont.woff2',
  weight: 'normal',
  display: 'swap'
})

// Entire font family with multiple variants
await loadFontFamily('MyFont', [
  { src: '/fonts/MyFont-Regular.woff2', weight: 'normal' },
  { src: '/fonts/MyFont-Bold.woff2', weight: 'bold' },
  { src: '/fonts/MyFont-Italic.woff2', weight: 'normal', style: 'italic' }
])

import { preloadFont, removeFontPreload } from 'metaowl'

// Preload a font
preloadFont('MyFont', '/fonts/MyFont.woff2', {
  weight: 'normal',
  type: 'font/woff2'
})

// Remove preload when no longer needed
removeFontPreload('MyFont', 'normal')

import { injectFontFaceRules } from 'metaowl'

injectFontFaceRules({
  family: 'MyFont',
  src: '/fonts/MyFont.woff2',
  weight: 'normal',
  display: 'swap'
})

// Or multiple at once
injectFontFaceRules([
  { family: 'MyFont', src: '/fonts/MyFont-Regular.woff2', weight: 'normal' },
  { family: 'MyFont', src: '/fonts/MyFont-Bold.woff2', weight: 'bold' }
])

import { measureTextWidth } from 'metaowl'

const width = measureTextWidth('Hello World', 'MyFont', 16)
// Returns: ~93.5 (pixels)

import { adjustFontForFout } from 'metaowl'

const el = document.querySelector('.text-with-custom-font')

await adjustFontForFout(el, 'sans-serif', 3000)
// Adds 'metaowl-font-loaded' when font is ready
// Adds 'metaowl-font-fout' after timeout as fallback
